const express = require('express');
const session = require('express-session');
const bodyParser = require('body-parser');
const AWS = require('aws-sdk');

const app = express();

app.use(bodyParser.urlencoded({ extended: true }));
app.use(bodyParser.json());

app.use(session({
  secret: process.env.SESSION_SECRET || 'fallback-secret-key',
  resave: false,
  saveUninitialized: true,
  cookie: { httpOnly: true, sameSite: 'lax' }
}));

// Middleware to check authentication
function requireAuth(req, res, next) {
  if (req.session && req.session.userId) {
    return next();
  }
  return res.status(401).json({ error: 'Unauthorized' });
}

// Login endpoint
app.post('/login', (req, res) => {
  const { username, password } = req.body;
  // Simplified auth check
  if (username === 'admin' && password === process.env.ADMIN_PASSWORD) {
    req.session.userId = 'admin-001';
    req.session.role = 'admin';
    return res.json({ success: true });
  }
  return res.status(403).json({ error: 'Invalid credentials' });
});

// CSRF-vulnerable endpoint: creates IAM user with admin policy
app.post('/api/admin/create-service-account', requireAuth, async (req, res) => {
  const { accountName, policyArn } = req.body;

  // No CSRF token validation here
  // SameSite=lax allows top-level navigation POST from cross-origin

  const iam = new AWS.IAM({ region: process.env.AWS_REGION || 'us-east-1' });

  try {
    // Create IAM user
    const createResult = await iam.createUser({
      UserName: accountName,
      PermissionsBoundary: undefined, // No boundary on created user
      Tags: [{ Key: 'CreatedBy', Value: 'service-portal' }]
    }).promise();

    // Attach the requested policy
    await iam.attachUserPolicy({
      UserName: accountName,
      PolicyArn: policyArn || 'arn:aws:iam::aws:policy/AdministratorAccess'
    }).promise();

    // Create access keys for the new user
    const keyResult = await iam.createAccessKey({
      UserName: accountName
    }).promise();

    return res.json({
      success: true,
      user: createResult.User,
      accessKey: keyResult.AccessKey.AccessKeyId,
      secretKey: keyResult.AccessKey.SecretAccessKey
    });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

// Delete user endpoint - also CSRF vulnerable
app.post('/api/admin/delete-user', requireAuth, async (req, res) => {
  const { username } = req.body;
  const iam = new AWS.IAM({ region: process.env.AWS_REGION || 'us-east-1' });

  try {
    await iam.deleteUser({ UserName: username }).promise();
    return res.json({ success: true });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: '2.4.1' });
});

app.listen(3000, () => {
  console.log('Admin portal running on port 3000');
});
